-- ============================================================================
-- 030 · agent_tool_require_confirmation.sql
-- ----------------------------------------------------------------------------
-- Per-tool opt-out for the caller-confirmation gate on call transfers.
--
-- `calls.update(twiml=<Dial>...)` takes the caller OUT of the backend's
-- WebSocket: the agent loses the audio and the conversation context, and
-- there is no way back. Until 2026-10-06 the only control was the prompt
-- section generated by agent_prompt_tools, which is not a control -- a
-- production call with `tool_choice=auto` and 3 tools registered had the
-- model emit a call_transfer on its own and transfer a caller to a
-- recruiter who had never asked for one.
--
-- The gate now lives in services/transfer_confirmation.py and is ON by
-- default for kind='call_transfer'. This column is how an operator turns
-- it OFF for a destination they trust.
--
-- NULL (not FALSE) is the intended "use the default" value, and is also
-- exactly what every pre-existing row looks like. So this is additive:
-- no backfill and no rewrite.
--
-- BEHAVIOUR CHANGE FOR EXISTING ROWS: they read as NULL, which the gate
-- treats as ON. Every call_transfer tool therefore starts asking the
-- caller first, immediately, without anyone opting in. That is the point
-- of the migration, but it is not a no-op, so it is worth stating
-- plainly rather than claiming otherwise. An operator who has a
-- destination they trust sets require_confirmation = FALSE to restore the
-- old behaviour for that one tool.
--
-- Only meaningful for kind='call_transfer'. Webhook tools have no
-- equivalent irreversibility, so the runtime ignores the column for them.
-- ============================================================================

ALTER TABLE agent_tools
  ADD COLUMN IF NOT EXISTS require_confirmation BOOLEAN;